import { useState } from "react";
import axios from "axios";

export default function Cadastro() {
  const [form, setForm] = useState({
    nome: "", idade: "", rua: "", bairro: "", estado: "", biografia: "", imagem: null
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const data = new FormData();
    for (let key in form) {
      if (key === "imagem") {
        const reader = new FileReader();
        reader.onload = () => {
          axios.post("http://localhost:3001/usuario", {
            ...form,
            imagem: reader.result
          }).then(() => alert("Usuário cadastrado com sucesso"))
            .catch(() => alert("Erro ao cadastrar usuário"));
        };
        reader.readAsDataURL(form.imagem);
      }
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      {["nome", "idade", "rua", "bairro", "estado"].map(campo => (
        <div className="mb-3" key={campo}>
          <input
            type={campo === "idade" ? "number" : "text"}
            className="form-control"
            placeholder={campo.charAt(0).toUpperCase() + campo.slice(1)}
            onChange={e => setForm({ ...form, [campo]: e.target.value })}
          />
        </div>
      ))}
      <div className="mb-3">
        <textarea
          className="form-control"
          placeholder="Biografia"
          onChange={e => setForm({ ...form, biografia: e.target.value })}
        ></textarea>
      </div>
      <div className="mb-3">
        <input type="file" className="form-control" onChange={e => setForm({ ...form, imagem: e.target.files[0] })} />
      </div>
      <button className="btn btn-success">Cadastrar</button>
    </form>
  );
}
